@dataclass
class VeloraConfig:
    """
    This is the sub-configuration class to store the configuration for VeLoRA.

    VeLoRA ("Memory Efficient Training using Rank-1 Sub-Token Projections",
    https://huggingface.co/papers/2405.17991) reduces the peak activation memory of LoRA training. Each token is split
    into `num_groups` sub-tokens which are projected onto a shared rank-1 vector; only the resulting compressed scalars
    are cached for the backward pass, where the activations are reconstructed from them.

    Args:
        num_groups (`int`):
            Number of sub-token groups each token is split into. Must be positive. Defaults to `64`.
        scale (`float`):
            Scaling factor applied when reconstructing the activations in the backward pass. Must be positive. Defaults
            to `1.0`.
        init_type (`str`):
            How the rank-1 projection vector is initialized. One of `"batch_average_once"` (computed from the first
            training batch and then frozen), `"batch_average"` (recomputed from every training batch) or `"random"` (a
            normalized random vector fixed at initialization). Defaults to `"batch_average"`.
    """

    num_groups: int = field(
        default=64,
        metadata={"help": "Number of sub-token groups each token is split into."},
    )
    scale: float = field(
        default=1.0,
        metadata={"help": "Scaling factor applied when reconstructing the activations in the backward pass."},
    )
    init_type: str = field(
        default="batch_average",
        metadata={
            "help": (
                "How the rank-1 projection vector is initialized. One of 'batch_average_once', 'batch_average' or "
                "'random'."
            )
        },
    )

    def __post_init__(self):
        if self.num_groups <= 0:
            raise ValueError(f"`num_groups` should be positive, got {self.num_groups}.")
        if self.scale <= 0.0:
            raise ValueError(f"`scale` should be positive, got {self.scale}.")
        if self.init_type not in ("batch_average_once", "batch_average", "random"):
            raise ValueError(
                f"Unsupported `init_type` '{self.init_type}'. Supported values are 'batch_average_once', "
                "'batch_average', and 'random'."
            )


